{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for high throughput on large spans.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (Vector512.IsHardwareAccelerated && values.Length >= Vector512<float>.Count * 2)
            return FindMinMax512(values);

        if (Vector256.IsHardwareAccelerated && values.Length >= Vector256<float>.Count * 2)
            return FindMinMax256(values);

        if (Vector128.IsHardwareAccelerated && values.Length >= Vector128<float>.Count * 2)
            return FindMinMax128(values);

        return FindMinMaxScalar(values);
    }

    private static (float Min, float Max) FindMinMax512(ReadOnlySpan<float> values)
    {
        ref float start = ref MemoryMarshal.GetReference(values);
        int count = Vector512<float>.Count;
        int lastBlockStart = values.Length - (values.Length % count);

        var vMin = Vector512.LoadUnsafe(ref start);
        var vMax = vMin;

        for (int i = count; i < lastBlockStart; i += count)
        {
            var v = Vector512.LoadUnsafe(ref start, (nuint)i);
            vMin = Vector512.Min(vMin, v);
            vMax = Vector512.Max(vMax, v);
        }

        // Reduce 512 -> scalar
        var min256Lo = vMin.GetLower();
        var min256Hi = vMin.GetUpper();
        var min256 = Vector256.Min(min256Lo, min256Hi);
        var max256Lo = vMax.GetLower();
        var max256Hi = vMax.GetUpper();
        var max256 = Vector256.Max(max256Lo, max256Hi);

        var min128Lo = min256.GetLower();
        var min128Hi = min256.GetUpper();
        var min128 = Vector128.Min(min128Lo, min128Hi);
        var max128Lo = max256.GetLower();
        var max128Hi = max256.GetUpper();
        var max128 = Vector128.Max(max128Lo, max128Hi);

        float min = HorizontalMin(min128);
        float max = HorizontalMax(max128);

        // Handle tail elements
        for (int i = lastBlockStart; i < values.Length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

