            vMin = Vector256.Min(vMin, v);
            vMax = Vector256.Max(vMax, v);
        }

        // Reduce 256 -> 128 -> scalar
        var min128 = Vector128.Min(vMin.GetLower(), vMin.GetUpper());
        var max128 = Vector128.Max(vMax.GetLower(), vMax.GetUpper());

        float min = HorizontalMin(min128);
        float max = HorizontalMax(max128);

        for (int i = lastBlockStart; i < values.Length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    private static (float Min, float Max) FindMinMax128(ReadOnlySpan<float> values)
    {
        ref float start = ref MemoryMarshal.GetReference(values);
        int count = Vector128<float>.Count;
        int lastBlockStart = values.Length - (values.Length % count);

        var vMin = Vector128.LoadUnsafe(ref start);
        var vMax = vMin;

